import json, re, urllib.request, urllib.error, concurrent.futures
keys={}
for f in ['nm_api_keys.txt','nm2_api.txt','.key_used','.key_current']:
    try: txt=open(f).read()
    except: continue
    for m in re.finditer(r'(nmk_live_[A-Za-z0-9_\-]{20,})',txt):
        keys.setdefault(m.group(1),f)
print("key unik:",len(keys))
def bal(k):
    r=urllib.request.Request('https://nomask.ai/api/credit-balance',headers={'Authorization':'Bearer '+k})
    try:
        with urllib.request.urlopen(r,timeout=30) as resp:
            j=json.load(resp); return k,j,None
    except urllib.error.HTTPError as e: return k,None,f'http{e.code}'
    except Exception as e: return k,None,type(e).__name__
live={}
with concurrent.futures.ThreadPoolExecutor(10) as ex:
    for k,j,err in ex.map(bal,list(keys)):
        if j is not None: live[k]=j
print("key hidup:",len(live))
for k,j in list(live.items())[:4]: print("  contoh:",json.dumps(j)[:200])
json.dump({k:v for k,v in live.items()},open('/tmp/nm_live.json','w'))
EOF
